from datetime import datetime
rows=pickle.load(open('/tmp/an/rows.pkl','rb'))
ext=datetime(2026,6,22,23,59)
man=[r for r in rows if r['workflow']=='manual'];ass=[r for r in rows if r['workflow']=='assist']
sev=['sev1','sev2','sev3']
wm={s:sum(r['severity']==s for r in man)/len(man) for s in sev}
wa={s:sum(r['severity']==s for r in ass)/len(ass) for s in sev}
def mean(g,k):
    g=[r[k] for r in g if r['ttc'] is not None];return st.mean(g)
for k in ['ttc','min']:
    pm={s:mean([r for r in man if r['severity']==s],k) for s in sev}
    pa={s:mean([r for r in ass if r['severity']==s],k) for s in sev}
    print(k,'manual mean',round(sum(wm[s]*pm[s] for s in sev),2),'assist observed-mix',round(sum(wa[s]*pa[s] for s in sev),2),'| at manual mix: manual',round(sum(wm[s]*pm[s] for s in sev),2),'assist',round(sum(wm[s]*pa[s] for s in sev),2),'| at assist mix: manual',round(sum(wa[s]*pm[s] for s in sev),2),'assist',round(sum(wa[s]*pa[s] for s in sev),2))
    print(' per-sev diff (assist-manual)',{s:round(pa[s]-pm[s],1) for s in sev})
# bootstrap CI of standardized diff (assist - manual at assist mix, closed only), resample within sev x workflow
random.seed(1)
def sd(k,w):
    out=[]
    for _ in range(4000):
        t=0
        for s in sev:
            a=[r[k] for r in ass if r['severity']==s and r['ttc'] is not None];m=[r[k] for r in man if r['severity']==s and r['ttc'] is not None]
            a=[random.choice(a) for _ in a];m=[random.choice(m) for _ in m]
            t+=w[s]*(st.mean(a)-st.mean(m))
        out.append(t)
    out.sort();return round(out[100],2),round(out[2000],2),round(out[3900],2)
for k in ['ttc','min']: print(k,'std diff at assist mix (lo,med,hi 95%)',sd(k,wa),' at manual mix',sd(k,wm))
# naive responder-minutes
nm=st.mean(r['min'] for r in man if r['ttc'] is not None);print('naive mean min diff',round(st.mean(r['min'] for r in ass if r['ttc'] is not None)-nm,1))
# median ttc naive 'headline' and per-incident hours "saved"
# Finance naive: median ttc diff *? 
# missing: censored lower bounds
print('open at extract (hours since open):')
for r in rows:
    if r['ttc'] is None: print(r['incident_id'],r['severity'],round((ext-r['o']).total_seconds()/3600))
# sensitivity: closed-only minutes by sev incl. missing at lower bound? sev1 assist unclosed 5/14; closed rate
for s in sev:
    for w,g in (('manual',man),('assist',ass)):
        x=[r for r in g if r['severity']==s];print(s,w,'unclosed',sum(r['ttc'] is None for r in x),'/',len(x))
# within-sev mins vs ttc ratio; time of day mix
for w,g in (('manual',man),('assist',ass)):
    print(w,'median open hour',st.median(r['o'].hour for r in g))
# pre-trend: manual week daily mean ttc
from collections import defaultdict
dd=defaultdict(list)
for r in rows:
    if r['ttc'] is not None: dd[r['o'].date()].append(r['severity'])
for k in sorted(dd): print(k,{s:dd[k].count(s) for s in sev})
# sev3 distribution check by day: ttc sev3
dd=defaultdict(list)
for r in rows:
    if r['ttc'] is not None and r['severity']=='sev3': dd[r['o'].date()].append(r['ttc'])
print({str(k):round(st.mean(v),2) for k,v in sorted(dd.items())})
# reopen & handoffs sev1 closed assist
for r in ass:
    if r['severity']=='sev1' and r['ttc'] is not None: print(r['incident_id'],round(r['ttc'],1),r['min'],r['ho'],r['reo'])
